from fastapi.sse import ServerSentEvent, _check_sse_field_valid

def test_sse_validation():
    print("--- Testing _check_sse_field_valid ---")

    # 1. Valid input
    try:
        _check_sse_field_valid("valid_string")
        print("PASS: Valid string input.")
    except Exception as e:
        print(f"FAIL: Valid string input failed with {e}")

    # 2. Invalid input for id (contains \n)
    try:
        _check_sse_field_valid("id_with_newline\n")
        print("FAIL: Newline in ID was not caught.")
    except ValueError as e:
        if "newline characters" in str(e):
            print("PASS: Newline in ID caught.")
        else:
            print(f"FAIL: Newline in ID caught wrong error: {e}")

    # 3. Invalid input for event (contains \r)
    try:
        _check_sse_field_valid("event_with_carriage_return\r")
        print("FAIL: CR in event was not caught.")
    except ValueError as e:
        if "newline characters" in str(e):
            print("PASS: CR in event caught.")
        else:
            print(f"FAIL: CR in event caught wrong error: {e}")

    # 4. Invalid input for id (contains \0)
    try:
        _check_sse_field_valid("id_with_null\0")
        print("FAIL: Null character in ID was not caught.")
    except ValueError as e:
        if "null characters" in str(e):
            print("PASS: Null character in ID caught.")
        else:
            print(f"FAIL: Null character in ID caught wrong error: {e}")

    # 5. None input
    try:
        _check_sse_field_valid(None)
        print("PASS: None input handled.")
    except Exception as e:
        print(f"FAIL: None input failed with {e}")

test_sse_validation()
